import {readVisitLocationPolicy} from './visit-location';
import {assessVisitLocation} from '../shared/visit-location';
import {assertRepVisitAvailable,repVisitAvailableGuard} from './visit-attendance';
import {readWorkPage} from './work-pages';
import {pipeline} from './pipeline';
import {Hono} from 'hono';import {z} from 'zod';import{operation,guard,fail,type OperationEnv,digest}from './operations';import{customerPredicate,type Scope}from './scope';import{businessClock,isWorkingInstant,calendarMinutesBetween,type WorkCalendar}from './calendar';
export const workflows=new Hono<OperationEnv>();const id=z.string().min(1).max(128),reason=z.string().trim().min(1).max(2000),instant=z.iso.datetime({offset:true}).transform(v=>new Date(v).toISOString()),channel=z.enum(['field','telesales']);
workflows.use('/api/telesales/*',async(c,next)=>{if(!c.get('scope').capabilities.includes('telesales:read'))return c.json({code:'SCOPE_DENIED'},403);await next()});
workflows.use('/api/*',async(c,next)=>{if(c.req.method==='POST'&&(/^\/api\/work-sessions\/[^/]+\/end$/.test(c.req.path)||/^\/api\/telesales\/queue\/[^/]+\/renew$/.test(c.req.path)||/^\/api\/(campaigns|scripts)\/[^/]+\/archive$/.test(c.req.path)||/^\/api\/attachments\/[^/]+\/finalize$/.test(c.req.path))){const body=await c.req.json().catch(()=>null);if(!z.object({}).strict().safeParse(body).success)return c.json({code:'EMPTY_BODY_REQUIRED'},422)}await next()});
async function customer(db:D1Database,s:Scope,rid:string,allowInactive=false){const f=customerPredicate(s);const co=await db.prepare("SELECT co.* FROM customer_outlet co WHERE co.id=? AND co.merged_into_id IS NULL AND "+(allowInactive?'':"co.record_status='active' AND " )+f.sql).bind(rid,...f.params).first<any>();if(!co)fail(404,'CUSTOMER_NOT_FOUND');return co}
function owns(s:Scope,row:any){return s.orgWide||s.allRepsInArea||s.repIds.includes(row.user_id)}
function etag(c:any,r:any){if(!r)fail(404,'NOT_FOUND');if(!c.req.header('If-Match'))fail(428,'IF_MATCH_REQUIRED');if(c.req.header('If-Match')!==`"${r.version}"`)fail(412,'VERSION_CONFLICT')}
async function calendar(db:D1Database,co:any){const r=await db.prepare('SELECT b.timezone,w.* FROM area a JOIN branch b ON b.organization_id=a.organization_id AND b.id=a.branch_id JOIN work_calendar w ON w.organization_id=b.organization_id AND w.branch_id=b.id AND w.status=\'active\' WHERE a.organization_id=? AND a.id=?').bind(co.organization_id,co.area_id).first<any>();if(!r)fail(409,'WORK_CALENDAR_REQUIRED');return{timezone:r.timezone,calendar:{weekdays:JSON.parse(r.weekdays_json),start_time:r.start_time,end_time:r.end_time,holidays:JSON.parse(r.holidays_json)} as WorkCalendar}}
async function recipient(db:D1Database,s:Scope,user:string,co:any,kind:string){if(!owns(s,{user_id:user}))fail(403,'ASSIGNEE_OUTSIDE_SCOPE');if(!await db.prepare(`SELECT u.id FROM app_user u JOIN customer_assignment ca ON ca.organization_id=u.organization_id AND ca.rep_id=u.id WHERE u.organization_id=? AND u.id=? AND u.status='active' AND ca.outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?)) AND ca.channel=? AND ca.effective_from_date<=? AND (ca.effective_to_date IS NULL OR ca.effective_to_date>?)`).bind(s.identity.organization_id,user,s.identity.organization_id,co.id,co.id,kind==='call'?'telesales':'field',s.date,s.date).first())fail(422,'CUSTOMER_ASSIGNMENT_REQUIRED')}
async function scopedRow(c:any,table:string,rid:string){const s=c.get('scope') as Scope;const r=await c.env.DB.prepare(`SELECT * FROM ${table} WHERE organization_id=? AND id=?`).bind(s.identity.organization_id,rid).first();if(!r||!owns(s,r))fail(404,'NOT_FOUND');if(r.customer_id)await customer(c.env.DB,s,r.customer_id,true);return r}
const plan=z.object({customer_id:id,user_id:id,scheduled_at:instant,kind:z.enum(['visit','call']),reason,repeat_weeks:z.number().int().min(1).max(12).default(1)}).strict();
workflows.get('/api/work-plans',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'work-plans',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope'),f=customerPredicate(s);return c.json({data:(await c.env.DB.prepare(`SELECT w.*,co.name customer_name FROM work_plan w JOIN customer_outlet co ON co.organization_id=w.organization_id AND co.id=w.customer_id WHERE ${f.sql} AND w.organization_id=?${s.orgWide||s.allRepsInArea?'':` AND w.user_id IN(${s.repIds.map(()=>'?').join(',')})`} ORDER BY scheduled_at,id`).bind(...f.params,s.identity.organization_id,...(s.orgWide||s.allRepsInArea?[]:s.repIds)).all()).results})});
workflows.post('/api/work-plans',async c=>{const b=plan.safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_WORK_PLAN'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),x=b.data,co=await customer(db,s,x.customer_id);await recipient(db,s,x.user_id,co,x.kind);const cal=await calendar(db,co);if(!isWorkingInstant(new Date(x.scheduled_at),cal.timezone,cal.calendar))fail(422,'OUTSIDE_WORKING_HOURS');if(Date.parse(x.scheduled_at)<Date.now())fail(422,'PAST_PLAN_REQUIRES_REVIEW');if(await db.prepare("SELECT id FROM work_plan WHERE organization_id=? AND user_id=? AND status IN('planned','proposed') AND ABS(julianday(scheduled_at)-julianday(?))*1440<30").bind(s.identity.organization_id,x.user_id,x.scheduled_at).first())fail(409,'SCHEDULE_COLLISION');const data={id:crypto.randomUUID(),...x,status:['SALES_REP','TELESALES'].includes(s.identity.role)?'proposed':'planned',version:1};const statements:D1PreparedStatement[]=[];const occurrences=[];for(let week=0;week<x.repeat_weeks;week++){const at=new Date(Date.parse(x.scheduled_at)+week*7*86400000).toISOString();if(!isWorkingInstant(new Date(at),cal.timezone,cal.calendar))fail(422,'RECURRENCE_OUTSIDE_WORKING_DAYS');if(x.kind==='visit'){const offDate=businessClock(new Date(at),cal.timezone).date;await assertRepVisitAvailable(db,s.identity.organization_id,x.user_id,offDate);statements.push(...repVisitAvailableGuard(db,s.identity.organization_id,x.user_id,offDate))}const rid=week===0?data.id:crypto.randomUUID();occurrences.push({id:rid,scheduled_at:at});statements.push(db.prepare('INSERT INTO work_plan(id,organization_id,customer_id,user_id,scheduled_at,original_scheduled_at,kind,status,reason,created_by,created_at,calendar_snapshot_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').bind(rid,s.identity.organization_id,x.customer_id,x.user_id,at,at,x.kind,data.status,x.reason,s.identity.id,new Date().toISOString(),JSON.stringify({...cal,visit_window:co.visit_window,slot_minutes:30,recurrence_weeks:x.repeat_weeks})))}return{resource:'work-plans',data:{...data,occurrences},status:201,statements}},false)});
workflows.put('/api/work-plans/:id',async c=>{const b=z.object({scheduled_at:instant,status:z.enum(['planned','cancelled']),reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_PLAN_CHANGE'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await scopedRow(c,'work_plan',c.req.param('id')!);etag(c,r);if(['SALES_REP','TELESALES'].includes(s.identity.role))fail(403,'SUPERVISOR_REQUIRED');if(!['planned','proposed'].includes(r.status))fail(409,'PLAN_CLOSED');if(b.data.status==='planned'){const co=await customer(db,s,r.customer_id),cal=await calendar(db,co);if(r.kind==='visit')await assertRepVisitAvailable(db,s.identity.organization_id,r.user_id,businessClock(new Date(b.data.scheduled_at),cal.timezone).date);if(!isWorkingInstant(new Date(b.data.scheduled_at),cal.timezone,cal.calendar))fail(422,'OUTSIDE_WORKING_HOURS');}const data={...r,...b.data,version:r.version+1};return{resource:'work-plans',before:r,data,statements:[...guard(db,db.prepare('UPDATE work_plan SET scheduled_at=?,status=?,reason=?,version=version+1 WHERE organization_id=? AND id=? AND version=?').bind(data.scheduled_at,data.status,data.reason,s.identity.organization_id,r.id,r.version)),db.prepare('INSERT INTO work_plan_revision VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,r.id,s.identity.id,new Date().toISOString(),JSON.stringify(r),JSON.stringify(data),data.reason)]}},false)});
workflows.get('/api/work-sessions',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'work-sessions',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope');return c.json({data:(await c.env.DB.prepare('SELECT * FROM work_session WHERE organization_id=? AND user_id=? ORDER BY started_at DESC LIMIT 100').bind(s.identity.organization_id,s.identity.id).all()).results})});
workflows.post('/api/work-sessions',async c=>{const b=z.object({kind:z.enum(['work','leave','training']),reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_SESSION'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),data={id:crypto.randomUUID(),...b.data,version:1,started_at:new Date().toISOString()};return{resource:'work-sessions',data,status:201,statements:[c.env.DB.prepare('INSERT INTO work_session(id,organization_id,user_id,kind,started_at,reason) VALUES(?,?,?,?,?,?)').bind(data.id,s.identity.organization_id,s.identity.id,data.kind,data.started_at,data.reason)]}},false)});
workflows.post('/api/work-sessions/:id/end',async c=>operation(c,{},async()=>{const s=c.get('scope'),db=c.env.DB,r=await scopedRow(c,'work_session',c.req.param('id')!);etag(c,r);if(r.user_id!==s.identity.id||r.ended_at)fail(409,'SESSION_NOT_OPEN');if(await db.prepare('SELECT activity_id FROM visit_active WHERE organization_id=? AND user_id=?').bind(s.identity.organization_id,s.identity.id).first())fail(409,'ACTIVE_VISIT_REQUIRES_CHECKOUT');const data={id:r.id,ended_at:new Date().toISOString(),version:r.version+1};return{resource:'work-sessions',before:r,data,statements:guard(db,db.prepare('UPDATE work_session SET ended_at=?,version=version+1 WHERE organization_id=? AND id=? AND version=? AND ended_at IS NULL').bind(data.ended_at,s.identity.organization_id,r.id,r.version))}},false));
const activityInput=z.object({customer_id:id,kind:z.enum(['visit','call']),notes:z.string().max(2000).default(''),plan_id:id.nullable().default(null)}).strict();
workflows.post('/api/activities',async c=>{const b=activityInput.safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_ACTIVITY'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),x=b.data,co=await customer(db,s,x.customer_id);await recipient(db,s,s.identity.id,co,x.kind);if(x.kind==='call')fail(422,'CALL_REQUIRES_QUEUE_LEASE');await assertRepVisitAvailable(db,s.identity.organization_id,s.identity.id,s.date);if(!await db.prepare("SELECT id FROM work_session WHERE organization_id=? AND user_id=? AND kind='work' AND ended_at IS NULL").bind(s.identity.organization_id,s.identity.id).first())fail(409,'WORK_SESSION_REQUIRED');if(x.plan_id&&!await db.prepare("SELECT id FROM work_plan WHERE organization_id=? AND id=? AND customer_id=? AND user_id=? AND kind='visit' AND status='planned'").bind(s.identity.organization_id,x.plan_id,co.id,s.identity.id).first())fail(422,'INVALID_PLAN');const data={id:crypto.randomUUID(),status:'draft',version:1,...x};return{resource:'activities',data,status:201,statements:[...repVisitAvailableGuard(db,s.identity.organization_id,s.identity.id,s.date),db.prepare("INSERT INTO activity(id,organization_id,outlet_id,user_id,channel,activity_kind,status,occurred_at,notes,metadata_json) VALUES(?,?,?,?,'field','visit','draft',?,?,?)").bind(data.id,s.identity.organization_id,co.id,s.identity.id,new Date().toISOString(),x.notes,JSON.stringify({plan_id:x.plan_id}))]}},false)});
workflows.get('/api/activities',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'activities',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope'),f=customerPredicate(s);return c.json({data:(await c.env.DB.prepare(`SELECT a.*,co.name customer_name FROM activity a JOIN customer_outlet co ON co.organization_id=a.organization_id AND co.id=a.outlet_id WHERE ${f.sql}${s.orgWide||s.allRepsInArea?'':` AND a.user_id IN(${s.repIds.map(()=>'?').join(',')})`}${s.channel?' AND a.channel=?':''} ORDER BY a.occurred_at DESC LIMIT 200`).bind(...f.params,...(s.orgWide||s.allRepsInArea?[]:s.repIds),...(s.channel?[s.channel]:[])).all()).results})});
const visit=z.object({occurred_at:instant,captured_at:instant.optional(),latitude_e7:z.number().int().min(-900000000).max(900000000).nullable(),longitude_e7:z.number().int().min(-1800000000).max(1800000000).nullable(),accuracy_cm:z.number().int().min(0).max(100000000).nullable(),source:z.enum(['browser_gps','android_gps','permission_denied','unavailable']),reason:z.string().max(2000).default(''),outcome:z.enum(['productive','follow_up','closed','no_pic','no_need']).optional(),notes:z.string().max(2000).default(''),next_action:z.object({title:reason,due_at:instant}).strict().optional()}).strict().refine(x=>(x.latitude_e7===null)===(x.longitude_e7===null));
for(const event of ['check-in','check-out'] as const)workflows.post('/api/visits/:id/'+event,async c=>{const b=visit.safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_VISIT_EVENT'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),a=await scopedRow(c,'activity',c.req.param('id')!);etag(c,a);if(a.user_id!==s.identity.id||a.activity_kind!=='visit'||a.status==='done')fail(409,'VISIT_NOT_EDITABLE');const x=b.data;if(Date.parse(x.occurred_at)>Date.now()+300000||Date.parse(x.occurred_at)<Date.now()-7*86400000)fail(422,'EVENT_TIME_REVIEW_REQUIRED');let quality='reported';const active=await db.prepare('SELECT * FROM visit_active WHERE organization_id=? AND user_id=?').bind(s.identity.organization_id,s.identity.id).first<any>();if(event==='check-in'&&active)fail(409,'VISIT_ALREADY_ACTIVE');if(event==='check-out'&&(!x.outcome||!x.notes||['follow_up','no_pic','closed'].includes(x.outcome)&&!x.next_action))fail(422,'OUTCOME_AND_NEXT_ACTION_REQUIRED');let transferred=false,co:any;try{co=await customer(db,s,a.outlet_id)}catch(e){if(event!=='check-out'||active?.activity_id!==a.id)throw e;co=await db.prepare('SELECT * FROM customer_outlet WHERE organization_id=? AND id=?').bind(s.identity.organization_id,a.outlet_id).first<any>();if(!co)throw e;transferred=true;}const locationPolicy=await readVisitLocationPolicy(db,s.identity.organization_id),assessment=assessVisitLocation(co,{...x,captured_at:x.captured_at??x.occurred_at},locationPolicy.config);
 const validation={...assessment,location_verified:assessment.location_verified&&Boolean(x.captured_at),policy_version:locationPolicy.version,capture_timestamp_supplied:Boolean(x.captured_at)};
 if(event==='check-in'&&!assessment.can_check_in)fail(422,'VISIT_LOCATION_NOT_ALLOWED');
 if(assessment.requires_reason&&!x.reason)fail(422,'VISIT_LOCATION_REASON_REQUIRED');
 if(assessment.requires_reason)quality='needs_review';
 const statements:D1PreparedStatement[]=[db.prepare('INSERT INTO master_mutation_guard(ok) SELECT COUNT(*) FROM customer_outlet WHERE organization_id=? AND id=? AND version=? AND latitude_e7 IS ? AND longitude_e7 IS ? AND coordinate_status=?').bind(s.identity.organization_id,co.id,co.version,co.latitude_e7,co.longitude_e7,co.coordinate_status),db.prepare('DELETE FROM master_mutation_guard'),db.prepare('INSERT INTO master_mutation_guard(ok) SELECT CASE WHEN COALESCE((SELECT version FROM visit_location_policy WHERE organization_id=?),0)=? THEN 1 ELSE 0 END').bind(s.identity.organization_id,locationPolicy.version),db.prepare('DELETE FROM master_mutation_guard')];let status='in_progress';if(event==='check-in'){await recipient(db,s,s.identity.id,co,'visit');const eventDate=businessClock(new Date(x.occurred_at),(await db.prepare('SELECT timezone FROM organization WHERE id=?').bind(s.identity.organization_id).first<any>())!.timezone).date;await assertRepVisitAvailable(db,s.identity.organization_id,s.identity.id,eventDate);statements.push(...repVisitAvailableGuard(db,s.identity.organization_id,s.identity.id,eventDate));if(!await db.prepare("SELECT id FROM work_session WHERE organization_id=? AND user_id=? AND kind='work' AND ended_at IS NULL").bind(s.identity.organization_id,s.identity.id).first())fail(409,'WORK_SESSION_REQUIRED');if(a.status!=='draft'&&a.status!=='pending_checkin')fail(409,'CHECKIN_ALREADY_RECORDED');const pending=await db.prepare("SELECT * FROM visit_event WHERE organization_id=? AND activity_id=? AND event_kind='check-out' ORDER BY occurred_at DESC LIMIT 1").bind(s.identity.organization_id,a.id).first<any>();if(pending){if(Date.parse(pending.occurred_at)<Date.parse(x.occurred_at))fail(409,'CHECKOUT_PRECEDES_CHECKIN');status='needs_review'}else statements.push(db.prepare('INSERT INTO visit_active VALUES(?,?,?,?)').bind(s.identity.organization_id,s.identity.id,a.id,x.occurred_at))}else{if(active&&active.activity_id!==a.id)fail(409,'DIFFERENT_VISIT_ACTIVE');if(active&&Date.parse(x.occurred_at)<Date.parse(active.started_at))fail(422,'CHECKOUT_PRECEDES_CHECKIN');status=!active?'pending_checkin':quality==='needs_review'||transferred?'needs_review':'done';if(active)statements.push(db.prepare('DELETE FROM visit_active WHERE organization_id=? AND activity_id=?').bind(s.identity.organization_id,a.id));if(x.next_action){const cal=await calendar(db,co);if(Date.parse(x.next_action.due_at)<=Date.now()||!isWorkingInstant(new Date(x.next_action.due_at),cal.timezone,cal.calendar))fail(422,'INVALID_FOLLOWUP_SLOT');statements.push(db.prepare('INSERT INTO sales_task(id,organization_id,customer_id,user_id,channel,title,due_at,original_due_at,created_by,reason) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,co.id,s.identity.id,'field',x.next_action.title,x.next_action.due_at,x.next_action.due_at,s.identity.id,'Visit follow-up'))}}
 const previousMetadata=JSON.parse(a.metadata_json);const metadata={...previousMetadata,location_validation:validation,check_in_validation:event==='check-in'?validation:previousMetadata.check_in_validation??null,location_validated:event==='check-out'&&validation.location_verified&&previousMetadata.check_in_validation?.location_verified===true&&previousMetadata.check_in_validation.customer_latitude_e7===assessment.customer_latitude_e7&&previousMetadata.check_in_validation.customer_longitude_e7===assessment.customer_longitude_e7,location_verification_pending:['missing_customer','unverified_customer'].includes(assessment.status),outcome:x.outcome||JSON.parse(a.metadata_json).outcome||null,meaningful:status==='done'&&['productive','follow_up'].includes(x.outcome||''),next_action:x.next_action||null,location_quality:quality,assignment_changed_during_visit:transferred};statements.push(db.prepare('INSERT INTO visit_event VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,a.id,s.identity.id,event,x.occurred_at,new Date().toISOString(),x.latitude_e7,x.longitude_e7,x.accuracy_cm,x.source,quality,JSON.stringify({...x,location_validation:validation})));if(quality==='needs_review'||status==='pending_checkin'||transferred)statements.push(db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,co.id,s.identity.id,a.id,'visit_location_or_sequence',x.reason||(transferred?'Customer assignment/status changed while visit was open':'Checkout arrived before checkin'),new Date().toISOString()));statements.push(...guard(db,db.prepare('UPDATE activity SET status=?,notes=?,metadata_json=?,version=version+1 WHERE organization_id=? AND id=? AND version=?').bind(status,x.notes||a.notes,JSON.stringify(metadata),s.identity.organization_id,a.id,a.version)));if(quality==='reported')statements.push(db.prepare('INSERT INTO sales_last_position(organization_id,user_id,latitude_e7,longitude_e7,captured_at,source,accuracy_m) VALUES(?,?,?,?,?,?,?) ON CONFLICT(organization_id,user_id) DO UPDATE SET latitude_e7=excluded.latitude_e7,longitude_e7=excluded.longitude_e7,captured_at=excluded.captured_at,source=excluded.source,accuracy_m=excluded.accuracy_m WHERE julianday(excluded.captured_at)>julianday(sales_last_position.captured_at)').bind(s.identity.organization_id,s.identity.id,x.latitude_e7,x.longitude_e7,x.occurred_at,'browser_event',Math.ceil((x.accuracy_cm||0)/100)));if(status==='done'&&metadata.plan_id)statements.push(db.prepare("UPDATE work_plan SET status='done',version=version+1 WHERE organization_id=? AND id=? AND user_id=?").bind(s.identity.organization_id,metadata.plan_id,s.identity.id));return{resource:'visits',before:a,data:{id:a.id,status,version:a.version+1,location_quality:quality,location_validation:validation},statements}},false)});
workflows.get('/api/tasks',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'tasks',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope'),f=customerPredicate(s);return c.json({data:(await c.env.DB.prepare(`SELECT t.*,co.name customer_name FROM sales_task t JOIN customer_outlet co ON co.organization_id=t.organization_id AND co.id=t.customer_id WHERE ${f.sql}${s.orgWide||s.allRepsInArea?'':` AND t.user_id IN(${s.repIds.map(()=>'?').join(',')})`} ORDER BY due_at,id`).bind(...f.params,...(s.orgWide||s.allRepsInArea?[]:s.repIds)).all()).results})});
workflows.post('/api/tasks',async c=>{const b=z.object({customer_id:id,user_id:id,channel,title:reason,due_at:instant,reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_TASK'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),db=c.env.DB,x=b.data,co=await customer(db,s,x.customer_id);await recipient(db,s,x.user_id,co,x.channel==='field'?'visit':'call');const cal=await calendar(db,co);if(Date.parse(x.due_at)<Date.now()||!isWorkingInstant(new Date(x.due_at),cal.timezone,cal.calendar))fail(422,'INVALID_TASK_SLOT');const data={id:crypto.randomUUID(),...x,status:'open',version:1};return{resource:'tasks',data,status:201,statements:[db.prepare('INSERT INTO sales_task(id,organization_id,customer_id,user_id,channel,title,due_at,original_due_at,created_by,reason) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(data.id,s.identity.organization_id,x.customer_id,x.user_id,x.channel,x.title,x.due_at,x.due_at,s.identity.id,x.reason)]}},false)});
workflows.post('/api/tasks/:id/complete',async c=>{const b=z.object({outcome:reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'TASK_OUTCOME_REQUIRED'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),r=await scopedRow(c,'sales_task',c.req.param('id')!);etag(c,r);if(!['open','in_progress'].includes(r.status))fail(409,'TASK_NOT_OPEN');return{resource:'tasks',before:r,data:{id:r.id,status:'done',version:r.version+1},statements:guard(c.env.DB,c.env.DB.prepare("UPDATE sales_task SET status='done',outcome=?,completed_at=?,version=version+1 WHERE organization_id=? AND id=? AND version=? AND status IN('open','in_progress')").bind(b.data.outcome,new Date().toISOString(),s.identity.organization_id,r.id,r.version))}},false)});
workflows.get('/api/handoffs',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'handoffs',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope'),f=customerPredicate(s);return c.json({data:(await c.env.DB.prepare(`SELECT h.*,co.name customer_name FROM sales_handoff h JOIN customer_outlet co ON co.organization_id=h.organization_id AND co.id=h.customer_id WHERE ${f.sql}${s.orgWide||s.allRepsInArea?'':` AND (h.sender_id IN(${s.repIds.map(()=>'?').join(',')}) OR h.receiver_id IN(${s.repIds.map(()=>'?').join(',')}))`} ORDER BY h.due_at,h.id`).bind(...f.params,...(s.orgWide||s.allRepsInArea?[]:[...s.repIds,...s.repIds])).all()).results})});
workflows.post('/api/handoffs',async c=>{const b=z.object({customer_id:id,receiver_id:id,channel,due_at:instant,need:reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_HANDOFF'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),x=b.data,co=await customer(db,s,x.customer_id);const assigned=await db.prepare('SELECT ca.id FROM customer_assignment ca JOIN app_user u ON u.organization_id=ca.organization_id AND u.id=ca.rep_id WHERE ca.organization_id=? AND ca.outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?)) AND ca.rep_id=? AND ca.channel=? AND ca.effective_from_date<=? AND (ca.effective_to_date IS NULL OR ca.effective_to_date>?) AND u.status=\'active\'').bind(s.identity.organization_id,s.identity.organization_id,co.id,co.id,x.receiver_id,x.channel,s.date,s.date).first();if(!assigned)fail(422,'RECEIVER_NOT_ASSIGNED');const cal=await calendar(db,co);if(Date.parse(x.due_at)<Date.now()||!isWorkingInstant(new Date(x.due_at),cal.timezone,cal.calendar))fail(422,'INVALID_HANDOFF_SLOT');const data={id:crypto.randomUUID(),...x,sender_id:s.identity.id,status:'pending',version:1};return{resource:'handoffs',data,status:201,statements:[db.prepare('INSERT INTO sales_handoff(id,organization_id,customer_id,sender_id,receiver_id,channel,due_at,need,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(data.id,s.identity.organization_id,x.customer_id,s.identity.id,x.receiver_id,x.channel,x.due_at,x.need,new Date().toISOString())]}},false)});
for(const action of ['accept','decline','complete','cancel'])workflows.post('/api/handoffs/:id/'+action,async c=>{const b=z.object({reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'REASON_REQUIRED'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await db.prepare('SELECT * FROM sales_handoff WHERE organization_id=? AND id=?').bind(s.identity.organization_id,c.req.param('id')!).first<any>();etag(c,r);await customer(db,s,r.customer_id,action!=='accept');if(action==='cancel'?r.sender_id!==s.identity.id:r.receiver_id!==s.identity.id)fail(403,'HANDOFF_ACTOR_REQUIRED');if(['accept','decline'].includes(action)&&r.status!=='pending'||action==='complete'&&r.status!=='accepted'||action==='cancel'&&!['pending','accepted'].includes(r.status))fail(409,'INVALID_HANDOFF_STATE');const status=({accept:'accepted',decline:'declined',complete:'completed',cancel:'cancelled'} as any)[action],tid=action==='accept'?crypto.randomUUID():r.task_id;const statements=guard(db,db.prepare('UPDATE sales_handoff SET status=?,reason=?,task_id=?,version=version+1 WHERE organization_id=? AND id=? AND version=?').bind(status,b.data.reason,tid,s.identity.organization_id,r.id,r.version));if(action==='accept'){const co=await customer(db,s,r.customer_id);await recipient(db,s,s.identity.id,co,r.channel==='field'?'visit':'call');if(await db.prepare("SELECT id FROM sales_task WHERE organization_id=? AND user_id=? AND status='open' AND ABS(julianday(due_at)-julianday(?))*1440<30").bind(s.identity.organization_id,r.receiver_id,r.due_at).first())fail(409,'CALENDAR_COLLISION');statements.push(db.prepare('INSERT INTO sales_task(id,organization_id,customer_id,user_id,channel,title,due_at,original_due_at,created_by,reason) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(tid,s.identity.organization_id,r.customer_id,r.receiver_id,r.channel,r.need,r.due_at,r.due_at,r.sender_id,'Accepted handoff'))}if(action==='decline')statements.push(db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,r.customer_id,r.sender_id,r.id,'handoff_declined',b.data.reason,new Date().toISOString()));return{resource:'handoffs',before:r,data:{id:r.id,status,version:r.version+1,task_id:tid},statements}},false)});
const campaign=z.object({name:z.string().trim().min(1).max(160),start_time:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),end_time:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),max_attempts:z.number().int().min(1).max(10),lease_seconds:z.number().int().min(60).max(300),hold_active_visit:z.boolean().default(true)}).strict().refine(x=>x.start_time<x.end_time);
for(const kind of ['campaigns','scripts'] as const){const table=kind==='campaigns'?'sales_campaign':'sales_script';workflows.get('/api/'+kind,async c=>{if(!c.get('scope').capabilities.includes('telesales:read'))return c.json({code:'SCOPE_DENIED'},403);return c.json({data:(await c.env.DB.prepare('SELECT * FROM '+table+' WHERE organization_id=? ORDER BY name,id').bind(c.get('identity').organization_id).all()).results})});workflows.post('/api/'+kind,async c=>{const b=(kind==='campaigns'?campaign:z.object({campaign_id:id,name:z.string().min(1).max(160),content:z.string().min(1).max(10000),qualification:z.array(z.string().min(1).max(160)).min(1).max(20)}).strict()).safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_CAMPAIGN_OR_SCRIPT'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),x=b.data as any,rid=crypto.randomUUID();if(kind==='scripts'&&!await db.prepare("SELECT id FROM sales_campaign WHERE organization_id=? AND id=? AND status='active'").bind(s.identity.organization_id,x.campaign_id).first())fail(422,'INVALID_CAMPAIGN');return{resource:kind,status:201,data:{id:rid,...x,status:'active',version:1},statements:[kind==='campaigns'?db.prepare('INSERT INTO sales_campaign(id,organization_id,name,start_time,end_time,max_attempts,lease_seconds,hold_active_visit) VALUES(?,?,?,?,?,?,?,?)').bind(rid,s.identity.organization_id,x.name,x.start_time,x.end_time,x.max_attempts,x.lease_seconds,x.hold_active_visit?1:0):db.prepare('INSERT INTO sales_script(id,organization_id,campaign_id,name,content,qualification_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(rid,s.identity.organization_id,x.campaign_id,x.name,x.content,JSON.stringify(x.qualification),new Date().toISOString())]}})});workflows.post('/api/'+kind+'/:id/archive',async c=>operation(c,{},async()=>{const db=c.env.DB,s=c.get('scope'),r=await db.prepare('SELECT * FROM '+table+' WHERE organization_id=? AND id=?').bind(s.identity.organization_id,c.req.param('id')!).first<any>();etag(c,r);return{resource:kind,before:r,data:{id:r.id,status:'archived',version:r.version+1},statements:guard(db,db.prepare('UPDATE '+table+" SET status='archived',version=version+1 WHERE organization_id=? AND id=? AND version=? AND status='active'").bind(s.identity.organization_id,r.id,r.version))}}))}
async function callEligibility(db:D1Database,s:Scope,co:any,contact:any,campaign:any){const reasons:string[]=[];if(!contact||contact.status!=='active'||contact.permission_status!=='allowed'||contact.preferred_channel!=='telesales')reasons.push('CONTACT_PERMISSION_REQUIRED');if(campaign?.status!=='active')reasons.push('CAMPAIGN_INACTIVE');const cal=await calendar(db,co);const now=new Date(),local=businessClock(now,cal.timezone);if(!isWorkingInstant(now,cal.timezone,cal.calendar)||local.time<campaign.start_time||local.time>=campaign.end_time)reasons.push('OUTSIDE_CONTACT_HOURS');const attempts=await db.prepare('SELECT COUNT(*) n FROM call_result WHERE organization_id=? AND (contact_id=? OR customer_id=?) AND occurred_at>=?').bind(s.identity.organization_id,contact?.id||'',co.id,new Date(Date.now()-86400000).toISOString()).first<any>();if(attempts.n>=campaign.max_attempts)reasons.push('ATTEMPT_LIMIT');if(await db.prepare("SELECT id FROM sales_task WHERE organization_id=? AND customer_id=? AND channel='telesales' AND status IN('open','in_progress') AND title LIKE 'Callback:%' AND due_at>?").bind(s.identity.organization_id,co.id,new Date().toISOString()).first())reasons.push('FUTURE_CALLBACK_HOLD');if(campaign.hold_active_visit&&await db.prepare('SELECT a.id FROM visit_active va JOIN activity a ON a.organization_id=va.organization_id AND a.id=va.activity_id WHERE a.organization_id=? AND a.outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?))').bind(s.identity.organization_id,s.identity.organization_id,co.id,co.id).first())reasons.push('ACTIVE_VISIT_HOLD');return reasons}
workflows.post('/api/telesales/queue/claim',async c=>{const b=z.object({customer_id:id,contact_id:id,campaign_id:id,script_id:id}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_QUEUE_CLAIM'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),x=b.data;if(!s.capabilities.includes('telesales:read'))fail(403,'TELESALES_REQUIRED');const co=await customer(db,s,x.customer_id);await recipient(db,s,s.identity.id,co,'call');const contact=await db.prepare('SELECT * FROM contact WHERE organization_id=? AND id=? AND customer_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?))').bind(s.identity.organization_id,x.contact_id,s.identity.organization_id,co.id,co.id).first<any>();const camp=await db.prepare('SELECT * FROM sales_campaign WHERE organization_id=? AND id=?').bind(s.identity.organization_id,x.campaign_id).first<any>();const script=await db.prepare("SELECT * FROM sales_script WHERE organization_id=? AND id=? AND campaign_id=? AND status='active'").bind(s.identity.organization_id,x.script_id,x.campaign_id).first<any>();if(!camp||!script)fail(422,'INVALID_CAMPAIGN_SCRIPT');const blocks=await callEligibility(db,s,co,contact,camp);if(blocks.length)fail(409,blocks.join(','));const now=new Date().toISOString(),expires=new Date(Date.now()+camp.lease_seconds*1000).toISOString(),rid=crypto.randomUUID();return{resource:'telesales-lease',status:201,data:{id:rid,version:1,expires_at:expires,phone:contact.phone,contact_name:contact.name,customer_id:co.id,script:{id:script.id,version:script.version,content:script.content,qualification:JSON.parse(script.qualification_json)},connection_verified:false},statements:[db.prepare("UPDATE telesales_lease SET status='expired',version=version+1 WHERE organization_id=? AND status='active' AND expires_at<=?").bind(s.identity.organization_id,now),db.prepare("INSERT INTO telesales_lease(id,organization_id,customer_id,contact_id,user_id,campaign_id,script_id,expires_at,status,script_snapshot_json) SELECT ?,?,?,?,?,?,?,?,'active',? WHERE EXISTS(SELECT 1 FROM contact WHERE organization_id=? AND id=? AND permission_status='allowed' AND status='active')").bind(rid,s.identity.organization_id,co.id,contact.id,s.identity.id,camp.id,script.id,expires,JSON.stringify(script),s.identity.organization_id,contact.id),db.prepare('INSERT INTO master_mutation_guard VALUES(changes())'),db.prepare('DELETE FROM master_mutation_guard')]}},false)});
workflows.post('/api/telesales/queue/:id/renew',async c=>operation(c,{},async()=>{const db=c.env.DB,s=c.get('scope'),r=await scopedRow(c,'telesales_lease',c.req.param('id')!);etag(c,r);if(r.user_id!==s.identity.id||r.status!=='active'||r.expires_at<=new Date().toISOString())fail(409,'LEASE_EXPIRED');const co=await customer(db,s,r.customer_id),ct=await db.prepare('SELECT * FROM contact WHERE organization_id=? AND id=?').bind(s.identity.organization_id,r.contact_id).first<any>(),camp=await db.prepare('SELECT * FROM sales_campaign WHERE organization_id=? AND id=?').bind(s.identity.organization_id,r.campaign_id).first<any>();const blocks=await callEligibility(db,s,co,ct,camp);if(blocks.length)fail(409,blocks.join(','));const expires=new Date(Date.now()+camp.lease_seconds*1000).toISOString();return{resource:'telesales-lease',before:r,data:{id:r.id,version:r.version+1,expires_at:expires},statements:guard(db,db.prepare('UPDATE telesales_lease SET expires_at=?,version=version+1 WHERE organization_id=? AND id=? AND version=? AND status=\'active\'').bind(expires,s.identity.organization_id,r.id,r.version))}},false));
const disposition=z.object({disposition:z.enum(['connected_pic','connected_non_pic','no_answer','busy','wrong_number','callback','not_interested','dnc']),notes:reason,callback_at:instant.nullable().default(null),qualification:z.record(z.string(),z.string().max(500)).default({})}).strict();
workflows.post('/api/telesales/queue/:id/complete',async c=>{const b=disposition.safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_DISPOSITION'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await scopedRow(c,'telesales_lease',c.req.param('id')!);etag(c,r);if(r.user_id!==s.identity.id||r.status!=='active'||r.expires_at<=new Date().toISOString())fail(409,'LEASE_EXPIRED');const x=b.data,co=await customer(db,s,r.customer_id),script=r.script_snapshot_json?JSON.parse(r.script_snapshot_json):await db.prepare('SELECT * FROM sales_script WHERE organization_id=? AND id=?').bind(s.identity.organization_id,r.script_id).first<any>();if(x.disposition==='connected_pic'&&JSON.parse(script.qualification_json).some((k:string)=>!x.qualification[k]))fail(422,'QUALIFICATION_REQUIRED');if(x.disposition==='callback'&&!x.callback_at)fail(422,'CALLBACK_REQUIRED');if(x.callback_at){const cal=await calendar(db,co);const camp=await db.prepare('SELECT * FROM sales_campaign WHERE organization_id=? AND id=?').bind(s.identity.organization_id,r.campaign_id).first<any>();const local=businessClock(new Date(x.callback_at),cal.timezone);if(Date.parse(x.callback_at)<Date.now()||!isWorkingInstant(new Date(x.callback_at),cal.timezone,cal.calendar)||local.time<camp.start_time||local.time>=camp.end_time)fail(422,'INVALID_CALLBACK_SLOT')}const rid=crypto.randomUUID(),now=new Date().toISOString(),statements=guard(db,db.prepare("UPDATE telesales_lease SET status='completed',version=version+1 WHERE organization_id=? AND id=? AND version=? AND status='active' AND expires_at>?").bind(s.identity.organization_id,r.id,r.version,now));statements.push(db.prepare('INSERT INTO call_result(id,organization_id,lease_id,customer_id,contact_id,user_id,disposition,notes,callback_at,occurred_at,script_snapshot_json,qualification_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').bind(rid,s.identity.organization_id,r.id,co.id,r.contact_id,s.identity.id,x.disposition,x.notes,x.callback_at,now,JSON.stringify(script),JSON.stringify(x.qualification)),db.prepare("INSERT INTO activity(id,organization_id,outlet_id,user_id,channel,activity_kind,status,occurred_at,notes,metadata_json) VALUES(?,?,?,?,'telesales','call','done',?,?,?)").bind(rid,s.identity.organization_id,co.id,s.identity.id,now,x.notes,JSON.stringify({...x,connection_evidence:'manual_unverified'})));if(x.disposition==='dnc')statements.push(db.prepare("UPDATE contact SET permission_status='dnc',permission_note=?,version=version+1 WHERE organization_id=? AND id=?").bind('Permintaan pelanggan pada panggilan: '+x.notes,s.identity.organization_id,r.contact_id));statements.push(db.prepare("UPDATE sales_task SET status='done',outcome=?,completed_at=?,version=version+1 WHERE organization_id=? AND customer_id=? AND user_id=? AND channel='telesales' AND status IN('open','in_progress') AND title LIKE 'Callback:%' AND due_at<=?").bind(x.disposition,now,s.identity.organization_id,co.id,s.identity.id,now));if(x.callback_at)statements.push(db.prepare('INSERT INTO sales_task(id,organization_id,customer_id,user_id,channel,title,due_at,original_due_at,created_by,reason) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.identity.organization_id,co.id,s.identity.id,'telesales','Callback: '+x.notes,x.callback_at,x.callback_at,s.identity.id,'Call disposition'));return{resource:'call-result',data:{id:rid,lease_id:r.id,status:'completed',connection_evidence:'manual_unverified',version:r.version+1},statements}},false)});
workflows.get('/api/exceptions',async c=>{if(c.req.query('limit')!==undefined||c.req.query('offset')!==undefined){const page=await readWorkPage(c.env.DB,c.get('scope'),'exceptions',c.req.query());return 'error' in page?c.json({code:page.error},422):c.json(page)}const s=c.get('scope'),f=customerPredicate(s);return c.json({data:(await c.env.DB.prepare(`SELECT e.*,co.name customer_name FROM sales_exception e LEFT JOIN customer_outlet co ON co.organization_id=e.organization_id AND co.id=e.customer_id WHERE e.organization_id=? AND (${f.sql})${s.orgWide||s.allRepsInArea?'':` AND e.user_id IN(${s.repIds.map(()=>'?').join(',')})`} ORDER BY e.created_at DESC LIMIT 200`).bind(s.identity.organization_id,...f.params,...(s.orgWide||s.allRepsInArea?[]:s.repIds)).all()).results})});
workflows.post('/api/attachment-intents',async c=>{const b=z.object({activity_id:id,size:z.number().int().min(1).max(5*1024*1024),mime:z.enum(['image/jpeg','image/png','application/pdf']),sha256:z.string().regex(/^[a-f0-9]{64}$/)}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_ATTACHMENT'},422);return operation(c,b.data,async()=>{if(!c.env.IMPORT_FILES)fail(503,'R2_NOT_CONFIGURED');const db=c.env.DB,s=c.get('scope'),x=b.data,a=await scopedRow(c,'activity',x.activity_id);await customer(db,s,a.outlet_id);if(a.user_id!==s.identity.id)fail(403,'ACTIVITY_OWNER_REQUIRED');const rid=crypto.randomUUID(),expires=new Date(Date.now()+3600000).toISOString();return{resource:'attachment-intents',status:201,data:{id:rid,version:1,upload_path:'/api/attachments/'+rid+'/upload',expires_at:expires},statements:[db.prepare('INSERT INTO evidence_attachment(id,organization_id,activity_id,user_id,storage_key,size,mime,sha256,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(rid,s.identity.organization_id,a.id,s.identity.id,'evidence/'+s.identity.organization_id+'/'+rid,x.size,x.mime,x.sha256,expires,new Date().toISOString())]}},false)});
async function attachment(c:any){const r=await scopedRow(c,'evidence_attachment',c.req.param('id')!);const a=await scopedRow(c,'activity',r.activity_id);await customer(c.env.DB,c.get('scope'),a.outlet_id,true);return r}
workflows.put('/api/attachments/:id/upload',async c=>{try{const r=await attachment(c);if(r.user_id!==c.get('identity').id||r.status!=='pending'||r.expires_at<=new Date().toISOString())return c.json({code:'UPLOAD_EXPIRED'},409);if(!c.env.IMPORT_FILES)return c.json({code:'R2_NOT_CONFIGURED'},503);if(c.req.header('Content-Type')!==r.mime||Number(c.req.header('Content-Length')||r.size)!==r.size)return c.json({code:'MIME_OR_SIZE_MISMATCH'},422);const bytes=await c.req.arrayBuffer();if(bytes.byteLength!==r.size||await digest(bytes)!==r.sha256)return c.json({code:'CHECKSUM_OR_SIZE_MISMATCH'},422);const v=new Uint8Array(bytes),valid=r.mime==='image/png'?v.slice(0,8).join(',')==='137,80,78,71,13,10,26,10':r.mime==='image/jpeg'?v[0]===255&&v[1]===216&&v[2]===255:new TextDecoder().decode(v.slice(0,5))==='%PDF-';if(!valid)return c.json({code:'FILE_SIGNATURE_MISMATCH'},422);await c.env.IMPORT_FILES.put(r.storage_key,bytes,{httpMetadata:{contentType:r.mime}});return c.json({data:{id:r.id,uploaded:true}})}catch{return c.json({code:'UPLOAD_UNAVAILABLE'},409)}});
workflows.post('/api/attachments/:id/finalize',async c=>operation(c,{},async()=>{const r=await attachment(c),db=c.env.DB,s=c.get('scope');etag(c,r);if(r.user_id!==s.identity.id||r.status!=='pending'||r.expires_at<=new Date().toISOString())fail(409,'UPLOAD_EXPIRED');const stored=await c.env.IMPORT_FILES?.get(r.storage_key);if(!stored)fail(409,'UPLOAD_NOT_FOUND');const bytes=await stored!.arrayBuffer();if(bytes.byteLength!==r.size||await digest(bytes)!==r.sha256)fail(422,'CHECKSUM_OR_SIZE_MISMATCH');return{resource:'attachments',before:r,data:{id:r.id,status:'ready',version:r.version+1},statements:guard(db,db.prepare("UPDATE evidence_attachment SET status='ready',version=version+1 WHERE organization_id=? AND id=? AND status='pending' AND version=?").bind(s.identity.organization_id,r.id,r.version))}},false));
workflows.get('/api/attachments/:id',async c=>{try{const r=await attachment(c);return c.json({data:{id:r.id,activity_id:r.activity_id,size:r.size,mime:r.mime,status:r.status,version:r.version,expires_at:r.expires_at}})}catch{return c.json({code:'NOT_FOUND'},404)}});
workflows.get('/api/attachments/:id/download',async c=>{try{const r=await attachment(c);if(r.status!=='ready')return c.json({code:'ATTACHMENT_NOT_READY'},409);const file=await c.env.IMPORT_FILES?.get(r.storage_key);if(!file)return c.json({code:'NOT_FOUND'},404);return new Response(file.body,{headers:{'Content-Type':r.mime,'Content-Disposition':'attachment; filename="evidence-'+r.id+'.'+(r.mime==='application/pdf'?'pdf':r.mime==='image/png'?'png':'jpg')+'"','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}})}catch{return c.json({code:'NOT_FOUND'},404)}});
const offlineEvent=z.object({client_event_id:id,type:z.enum(['activity','check_in','check_out','task_complete','call_complete','order','lead','forecast']),resource_id:id.optional(),version:z.number().int().positive().optional(),payload:z.record(z.string(),z.unknown())}).strict();
workflows.post('/api/sync/events',async c=>{const b=z.object({events:z.array(offlineEvent).min(1).max(1)}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_SYNC_ENVELOPE'},422);const results=[];for(const e of b.data.events){if(!['activity','order','lead','forecast'].includes(e.type)&&(!e.resource_id||!e.version)){results.push({client_event_id:e.client_event_id,status:'rejected',code:'RESOURCE_AND_VERSION_REQUIRED'});continue}const path=e.type==='order'?'/api/orders':e.type==='lead'?'/api/leads':e.type==='forecast'?'/api/forecast-contributions':e.type==='activity'?'/api/activities':e.type==='check_in'?'/api/visits/'+e.resource_id+'/check-in':e.type==='check_out'?'/api/visits/'+e.resource_id+'/check-out':e.type==='task_complete'?'/api/tasks/'+e.resource_id+'/complete':'/api/telesales/queue/'+e.resource_id+'/complete';const h=new Hono<OperationEnv>();h.use('*',async(x,next)=>{x.set('identity',c.get('identity'));x.set('scope',c.get('scope'));await next()});h.route('/',workflows);h.route('/',pipeline);const res=await h.request(path,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':e.client_event_id,...(e.version?{'If-Match':`"${e.version}"`}:{})},body:JSON.stringify(e.payload)},c.env);results.push({client_event_id:e.client_event_id,status:res.ok?'synced':[409,412,422,428].includes(res.status)?'review':'rejected',http_status:res.status,result:await res.json(),acknowledged_at:new Date().toISOString()})}return c.json({data:results})});
workflows.put('/api/tasks/:id',async c=>{const b=z.object({due_at:instant,reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_TASK_REVISION'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),db=c.env.DB,r=await scopedRow(c,'sales_task',c.req.param('id')!);etag(c,r);if(!['open','in_progress'].includes(r.status))fail(409,'TASK_NOT_OPEN');const customerRow=await customer(db,s,r.customer_id),cal=await calendar(db,customerRow);if(Date.parse(b.data.due_at)<Date.now()||!isWorkingInstant(new Date(b.data.due_at),cal.timezone,cal.calendar))fail(422,'INVALID_TASK_SLOT');return{resource:'tasks',before:r,data:{id:r.id,due_at:b.data.due_at,original_due_at:r.original_due_at,version:r.version+1},statements:guard(db,db.prepare('UPDATE sales_task SET due_at=?,reason=?,version=version+1 WHERE organization_id=? AND id=? AND version=?').bind(b.data.due_at,b.data.reason,s.identity.organization_id,r.id,r.version))}},false)});
workflows.post('/api/activities/:id/revisions',async c=>{const b=z.object({outcome:z.enum(['productive','follow_up','closed','no_pic','no_need']),notes:reason,reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_ACTIVITY_REVISION'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),db=c.env.DB,r=await scopedRow(c,'activity',c.req.param('id')!);etag(c,r);await customer(db,s,r.outlet_id);if(!['needs_review','done'].includes(r.status))fail(409,'ACTIVITY_REQUIRES_COMPLETE_EVENTS');if(r.status==='needs_review'&&!['MANAGEMENT','NSM','SUPERVISOR','REGIONAL_MANAGER','AREA_MANAGER'].includes(s.identity.role))fail(403,'REVIEWER_REQUIRED');const meta={...JSON.parse(r.metadata_json),outcome:b.data.outcome,meaningful:['productive','follow_up'].includes(b.data.outcome),review:{actor:s.identity.id,reason:b.data.reason,reviewed_at:new Date().toISOString()}};if(['follow_up','closed','no_pic'].includes(b.data.outcome)&&!meta.next_action)fail(422,'NEXT_ACTION_REQUIRED');return{resource:'activity-revisions',before:r,data:{id:r.id,status:'done',version:r.version+1},statements:guard(db,db.prepare("UPDATE activity SET status='done',notes=?,metadata_json=?,version=version+1 WHERE organization_id=? AND id=? AND version=?").bind(b.data.notes,JSON.stringify(meta),s.identity.organization_id,r.id,r.version))}},false)});
workflows.get('/api/telesales/workbench',async c=>{const s=c.get('scope'),db=c.env.DB;if(!s.capabilities.includes('telesales:read'))return c.json({code:'SCOPE_DENIED'},403);const f=customerPredicate(s),data=(await db.prepare(`SELECT co.id,co.name,co.area_id,(SELECT json_group_array(json_object('id',ct.id,'name',ct.name,'permission_status',ct.permission_status,'status',ct.status,'preferred_channel',ct.preferred_channel)) FROM contact ct WHERE ct.organization_id=co.organization_id AND ct.customer_id IN(SELECT f.id FROM customer_outlet f WHERE f.organization_id=co.organization_id AND(f.id=co.id OR f.merged_into_id=co.id)) AND ct.status='active') contacts_json,EXISTS(SELECT 1 FROM telesales_lease lease WHERE lease.organization_id=co.organization_id AND lease.customer_id=co.id AND lease.status='active' AND lease.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) lease_active,(SELECT MIN(t.due_at) FROM sales_task t WHERE t.organization_id=co.organization_id AND t.customer_id=co.id AND t.channel='telesales' AND t.status='open') callback_at,(SELECT MAX(i.invoice_date) FROM invoice i WHERE i.organization_id=co.organization_id AND i.outlet_id=co.id AND i.is_current=1 AND i.status='validated') last_invoice_date,(SELECT MIN(l.next_due_at) FROM sales_lead l WHERE l.organization_id=co.organization_id AND l.customer_id=co.id AND l.stage NOT IN('won','lost')) lead_due_at,(SELECT COUNT(*) FROM sales_lead l WHERE l.organization_id=co.organization_id AND l.customer_id=co.id AND l.stage='new') new_lead FROM customer_outlet co WHERE ${f.sql} AND co.record_status='active' AND co.merged_into_id IS NULL AND EXISTS(SELECT 1 FROM customer_assignment ca WHERE ca.organization_id=co.organization_id AND ca.outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=co.organization_id AND (id=co.id OR merged_into_id=co.id)) AND ca.channel='telesales' AND ca.effective_from_date<=? AND (ca.effective_to_date IS NULL OR ca.effective_to_date>?)${s.orgWide||s.allRepsInArea?'':` AND ca.rep_id IN(${s.repIds.map(()=>'?').join(',')})`}) ORDER BY CASE WHEN callback_at IS NOT NULL AND callback_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') THEN 0 WHEN callback_at IS NOT NULL THEN 1 WHEN new_lead>0 THEN 2 WHEN lead_due_at<strftime('%Y-%m-%dT%H:%M:%fZ','now') THEN 3 ELSE 4 END,callback_at,lead_due_at,last_invoice_date,co.id`).bind(...f.params,s.date,s.date,...(s.orgWide||s.allRepsInArea?[]:s.repIds)).all<any>()).results;for(const row of data){row.contacts=JSON.parse(row.contacts_json);delete row.contacts_json;row.lease_active=Boolean(row.lease_active)}return c.json({data})});
export async function salesMaintenance(db:D1Database,bucket?:R2Bucket){const now=new Date().toISOString();await db.prepare("UPDATE telesales_lease SET status='expired',version=version+1 WHERE status='active' AND expires_at<=?").bind(now).run();const pending=(await db.prepare("SELECT id,storage_key,organization_id FROM evidence_attachment WHERE status='pending' AND expires_at<=? LIMIT 100").bind(now).all<any>()).results;if(bucket)for(const a of pending){await bucket.delete(a.storage_key);await db.prepare("UPDATE evidence_attachment SET status='expired',version=version+1 WHERE id=? AND organization_id=? AND status='pending'").bind(a.id,a.organization_id).run()}const leads=(await db.prepare("SELECT l.*,co.area_id FROM sales_lead l JOIN customer_outlet co ON co.id=l.customer_id AND co.organization_id=l.organization_id WHERE l.stage NOT IN('won','lost')").all<any>()).results;for(const l of leads){let cal;try{cal=await calendar(db,l)}catch{continue}const meaningful=await db.prepare("SELECT MIN(occurred_at) first_at,MAX(occurred_at) last_at FROM activity WHERE organization_id=? AND user_id=? AND outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?)) AND status='done' AND occurred_at>=? AND (json_extract(metadata_json,'$.meaningful')=1 OR json_extract(metadata_json,'$.disposition')='connected_pic')").bind(l.organization_id,l.user_id,l.organization_id,l.customer_id,l.customer_id,l.created_at).first<any>();if(!meaningful.first_at&&calendarMinutesBetween(new Date(l.created_at),new Date(),cal.timezone,cal.calendar)>=240)await db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),l.organization_id,l.customer_id,l.user_id,l.id,'lead_response_sla','Belum ada respons bermakna setelah empat jam kerja.',now).run();const start=businessClock(new Date(meaningful.last_at||l.created_at),cal.timezone).date,end=businessClock(new Date(),cal.timezone).date;let days=0;for(let d=Date.parse(start)+86400000;d<=Date.parse(end)&&days<7;d+=86400000){const day=new Date(d).toISOString().slice(0,10),weekday=new Date(d).getUTCDay()||7;if(cal.calendar.weekdays.includes(weekday)&&!cal.calendar.holidays.includes(day))days++}if(days>=7||l.next_due_at<now)await db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),l.organization_id,l.customer_id,l.user_id,l.id,days>=7?'pipeline_stagnation':'pipeline_followup_overdue',days>=7?'Stage belum bergerak selama tujuh hari kerja.':'Next action melewati tenggat.',now).run()}const lateTasks=(await db.prepare("SELECT t.* FROM sales_task t WHERE t.status IN('open','in_progress') AND t.due_at<? AND NOT EXISTS(SELECT 1 FROM sales_exception e WHERE e.organization_id=t.organization_id AND e.resource_id=t.id AND e.kind='task_overdue' AND e.status='open') LIMIT 100").bind(now).all<any>()).results;for(const t of lateTasks)await db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),t.organization_id,t.customer_id,t.user_id,t.id,'task_overdue','Task melewati tenggat; jadwal asli '+t.original_due_at,now).run();const handoffs=(await db.prepare("SELECT h.*,co.area_id FROM sales_handoff h JOIN customer_outlet co ON co.organization_id=h.organization_id AND co.id=h.customer_id WHERE h.status='pending' AND h.created_at IS NOT NULL").all<any>()).results;for(const h of handoffs){try{const cal=await calendar(db,h);if(calendarMinutesBetween(new Date(h.created_at),new Date(),cal.timezone,cal.calendar)>=240)await db.prepare('INSERT OR IGNORE INTO sales_exception(id,organization_id,customer_id,user_id,resource_id,kind,reason,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),h.organization_id,h.customer_id,h.sender_id,h.id,'handoff_response_sla','Belum ada respons setelah empat jam kerja.',now).run()}catch{continue}}}
for(const [path,table]of [['work-plans','work_plan'],['work-sessions','work_session'],['activities','activity'],['tasks','sales_task']] as const)workflows.get('/api/'+path+'/:id',async c=>{try{const row=await scopedRow(c,table,c.req.param('id')!);if(row.outlet_id)await customer(c.env.DB,c.get('scope'),row.outlet_id);return c.json({data:row})}catch{return c.json({code:'NOT_FOUND'},404)}});
workflows.get('/api/handoff-recipients',async c=>{try{const s=c.get('scope'),co=await customer(c.env.DB,s,c.req.query('customer_id')||'');return c.json({data:(await c.env.DB.prepare("SELECT DISTINCT u.id,u.name,ca.channel FROM customer_assignment ca JOIN app_user u ON u.organization_id=ca.organization_id AND u.id=ca.rep_id WHERE ca.organization_id=? AND ca.outlet_id IN(SELECT id FROM customer_outlet WHERE organization_id=? AND (id=? OR merged_into_id=?)) AND ca.effective_from_date<=? AND (ca.effective_to_date IS NULL OR ca.effective_to_date>?) AND u.status='active' ORDER BY u.name").bind(s.identity.organization_id,s.identity.organization_id,co.id,co.id,s.date,s.date).all()).results})}catch{return c.json({code:'NOT_FOUND'},404)}});
for(const action of ['start','cancel'])workflows.post('/api/tasks/:id/'+action,async c=>{const b=z.object({reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'REASON_REQUIRED'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await scopedRow(c,'sales_task',c.req.param('id')!);etag(c,r);if(!['open','in_progress'].includes(r.status))fail(409,'TASK_NOT_OPEN');return{resource:'tasks',before:r,data:{id:r.id,status:action==='start'?'in_progress':'cancelled',version:r.version+1},statements:guard(db,db.prepare('UPDATE sales_task SET status=?,reason=?,version=version+1 WHERE organization_id=? AND id=? AND version=?').bind(action==='start'?'in_progress':'cancelled',b.data.reason,s.identity.organization_id,r.id,r.version))}},false)});
workflows.post('/api/exceptions/:id/resolve',async c=>{const b=z.object({reason}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'REASON_REQUIRED'},422);return operation(c,b.data,async()=>{const s=c.get('scope'),db=c.env.DB,r=await scopedRow(c,'sales_exception',c.req.param('id')!);if(!['MANAGEMENT','NSM','REGIONAL_MANAGER','AREA_MANAGER','SUPERVISOR'].includes(s.identity.role))fail(403,'REVIEWER_REQUIRED');if(r.status!=='open')fail(409,'EXCEPTION_ALREADY_REVIEWED');return{resource:'exceptions',before:r,data:{id:r.id,status:'reviewed'},statements:guard(db,db.prepare("UPDATE sales_exception SET status='reviewed',reason=reason||' | Review: '||? WHERE organization_id=? AND id=? AND status='open'").bind(b.data.reason,s.identity.organization_id,r.id))}},false)});
workflows.put('/api/campaigns/:id',async c=>{const b=campaign.safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_CAMPAIGN'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await db.prepare('SELECT * FROM sales_campaign WHERE organization_id=? AND id=?').bind(s.identity.organization_id,c.req.param('id')!).first<any>();etag(c,r);if(r.status!=='active')fail(409,'CAMPAIGN_ARCHIVED');const x=b.data;return{resource:'campaigns',before:r,data:{id:r.id,...x,version:r.version+1,status:'active'},statements:guard(db,db.prepare("UPDATE sales_campaign SET name=?,start_time=?,end_time=?,max_attempts=?,lease_seconds=?,hold_active_visit=?,version=version+1 WHERE organization_id=? AND id=? AND version=? AND status='active'").bind(x.name,x.start_time,x.end_time,x.max_attempts,x.lease_seconds,x.hold_active_visit?1:0,s.identity.organization_id,r.id,r.version))}})});
workflows.put('/api/scripts/:id',async c=>{const b=z.object({name:z.string().trim().min(1).max(160),content:z.string().min(1).max(10000),qualification:z.array(z.string().min(1).max(160)).min(1).max(20)}).strict().safeParse(await c.req.json().catch(()=>null));if(!b.success)return c.json({code:'INVALID_SCRIPT'},422);return operation(c,b.data,async()=>{const db=c.env.DB,s=c.get('scope'),r=await db.prepare('SELECT * FROM sales_script WHERE organization_id=? AND id=?').bind(s.identity.organization_id,c.req.param('id')!).first<any>();etag(c,r);if(r.status!=='active')fail(409,'SCRIPT_ARCHIVED');return{resource:'scripts',before:r,data:{id:r.id,...b.data,status:'active',version:r.version+1},statements:guard(db,db.prepare("UPDATE sales_script SET name=?,content=?,qualification_json=?,version=version+1 WHERE organization_id=? AND id=? AND version=? AND status='active'").bind(b.data.name,b.data.content,JSON.stringify(b.data.qualification),s.identity.organization_id,r.id,r.version))}})});
for(const[path,table]of [['campaigns','sales_campaign'],['scripts','sales_script']]as const)workflows.get('/api/'+path+'/:id',async c=>{if(!c.get('scope').capabilities.includes('telesales:read'))return c.json({code:'SCOPE_DENIED'},403);const r=await c.env.DB.prepare('SELECT * FROM '+table+' WHERE organization_id=? AND id=?').bind(c.get('identity').organization_id,c.req.param('id')!).first();return r?c.json({data:r}):c.json({code:'NOT_FOUND'},404)});
export const workflowRequestSchemas={plan,activity:activityInput,visit,campaign,disposition,offlineEvent};

export const workflowsInlineSchemas={'INVALID_PLAN_CHANGE':z.object({scheduled_at:instant,status:z.enum(['planned','cancelled']),reason}).strict(),'INVALID_SESSION':z.object({kind:z.enum(['work','leave','training']),reason}).strict(),'INVALID_TASK':z.object({customer_id:id,user_id:id,channel,title:reason,due_at:instant,reason}).strict(),'TASK_OUTCOME_REQUIRED':z.object({outcome:reason}).strict(),'INVALID_HANDOFF':z.object({customer_id:id,receiver_id:id,channel,due_at:instant,need:reason}).strict(),'REASON_REQUIRED':z.object({reason}).strict(),'INVALID_QUEUE_CLAIM':z.object({customer_id:id,contact_id:id,campaign_id:id,script_id:id}).strict(),'INVALID_ATTACHMENT':z.object({activity_id:id,size:z.number().int().min(1).max(5*1024*1024),mime:z.enum(['image/jpeg','image/png','application/pdf']),sha256:z.string().regex(/^[a-f0-9]{64}$/)}).strict(),'INVALID_SYNC_ENVELOPE':z.object({events:z.array(offlineEvent).min(1).max(1)}).strict(),'INVALID_TASK_REVISION':z.object({due_at:instant,reason}).strict(),'INVALID_ACTIVITY_REVISION':z.object({outcome:z.enum(['productive','follow_up','closed','no_pic','no_need']),notes:reason,reason}).strict(),'INVALID_SCRIPT':z.object({name:z.string().trim().min(1).max(160),content:z.string().min(1).max(10000),qualification:z.array(z.string().min(1).max(160)).min(1).max(20)}).strict()};
